# -*- coding: utf-8 -*-
"""v41 第三批：47个城市探索 v37 占位节点重写"""

R = [
("city_jiaohui_explore","交汇城·街市","你走进交汇城最热闹的街市。叫卖声、讨价声、铁匠的锤声，混成一片喧嚣的海洋。","你挤过人群，看见一个卖香料的老贩子正往布袋里装香料，一双手被香料染成了黄褐色。旁边，几个孩子在追一只偷了鱼干的猫，猫窜上屋顶，冲他们甩了甩尾巴。","街市的尽头，有一座不起眼的旧书摊。摊主是个戴眼镜的老人，正低头补书。你在他摊前蹲下，翻起一本发黄的旧书——里面夹着一张地图，画着一条通往城外的密道。","你抬头想问价，老人头也不抬：「那本书不卖。但你可以抄。」你借了纸笔，把地图抄了下来。谢过老人，你把地图收好，转身挤回人潮里。",[("按地图找密道","city_jiaohui_mystery"),("继续逛街市","city_jiaohui_suspicious")]),
("city_jiaohui_herb_quest","交汇城·草药任务","商会的王管事找到你，递给你一张清单：「城东的药铺缺一批草药，你跑一趟南门外的草药田，找李婆子要。」","你去了南门。草药田在城外，田垄整齐，空气里弥漫着药香。李婆子是个精瘦的老妇，正在田里拔草。她看了清单，点点头：「都有。就是最后一味，得去田边的水塘里捞。」","你在水塘里捞了半天，捞上一株湿淋淋的水草。李婆子接过去，就着水洗净：「这是水薄荷，治热病的。城东最近病了不少人，就缺这个。」","你把草药背回城东，药铺掌柜多给了你几个铜板：「跑得利索。以后有活，还找你。」你掂了掂铜板，心想：今天总算没白跑。",[("回商会交差","city_jiaohui_intro"),("打听城东的病","city_jiaohui_inn")]),
("city_jiaohui_inn","交汇城·旅店","傍晚，你走进城中的「跛脚酒桶」旅店。店里人声嘈杂，麦酒的味道混着汗味和柴火气。","你要了一碗热汤，在角落坐下。邻桌坐着几个商人，正压着嗓子说话：「……城北那间仓库，最近进出的人越来越多了。」「嘘，别打听。那地方，不干净。」","你低头喝汤，耳朵却没闲着。仓库——又是仓库。你想起在贫民窟时见过的那些木箱。这座城，表面越热闹，底下的暗流就越深。","你喝完汤，回房间躺下。窗外，交汇城的灯火亮得晃眼。你闭上眼睛，想着那些商人的话，迟迟没有睡着。",[("夜里出去看看","city_jiaohui_mystery"),("睡一觉再说","city_jiaohui_explore")]),
("city_jiaohui_mercury_queen","交汇城·墨丘利谈女王","你在图书馆的角落找到墨丘利。他面前摊着一本摊开的古籍，正用羽毛笔写着什么。","「女王？」他听了你的问题，放下笔，「你指的是哪一位？银叶的精灵女王，还是那位传说中被困在封印里的『傲慢之心』？」","「傲慢之心。」你说。墨丘利沉默了一会儿：「那是一枚活着的封印。它困住了一个女王——不是铁王座上的那种女王，而是一个用骄傲把自己困了三千年的人。」","「她还在等一个不骄傲的人，来替她开门。」他合上古籍，「如果你要去找她——记得，先放下你自己的骄傲。」",[("记住他的话","city_jiaohui_mercury_seals"),("再问封印的事","city_jiaohui_mercury_seals")]),
("city_jiaohui_mercury_seals","交汇城·墨丘利谈封印","「七印的事，你知道多少？」墨丘利问你。你摇摇头：「只知道有七道，散在大陆各处。」","墨丘利在纸上画了七个圈：「饥饿、愤怒、傲慢、贪婪、嫉妒、懒惰、色欲。七种原初之物，七道被遗忘的封印。每一道，都对应人心最深的缺口。」","「黄林晶——」他说出这个名字时，语气顿了顿，「一千年前，他布下这一切。但他留下的不只是封印，还有一堆没解完的谜。」","他抬起头看着你：「你既然走到这里，说明你也卷进来了。那就记住一句话：封印不是用来锁东西的——是用来提醒我们，有些东西，锁不住。」",[("问他黄林晶是谁","city_jiaohui_mercury_seraph"),("问灵魂魔法的事","city_jiaohui_mercury_soul")]),
("city_jiaohui_mercury_seraph","交汇城·墨丘利谈炽天使","「炽天使？」墨丘利听到这个词，罕见地露出凝重的神色，「你为什么问这个？」","「路上听人提起。」你说。他没有立刻回答，而是起身，把图书馆的门关上了。","「炽天使不是天使。」他压低声音，「是一种仪式——把活人的灵魂锻造成兵器。教会声称那是神圣的，但我知道，那东西……」他没有说完。","他重新坐下，声音恢复了平静：「如果你听到有人在讨论炽天使，离远一点。那不是你该碰的东西——至少现在不是。」",[("记下这个名字","city_jiaohui_mercury_soul"),("问灵魂魔法","city_jiaohui_mercury_soul")]),
("city_jiaohui_mercury_soul","交汇城·墨丘利谈灵魂魔法","「灵魂魔法不是邪术。」墨丘利说这句话时，语气格外坚定，「它只是被教会贴上了邪术的标签。」","「灵魂魔法触碰的是人内心最真实的东西——记忆、情感、执念。教会不会承认它，因为承认了它，就等于承认灵魂深处有他们管不到的地方。」","你想起圣城那些被抓走的灵魂法师。墨丘利像是看穿了你的心思：「我当年从圣城离开，就是因为……我不愿意再看着他们，把活生生的人当柴火烧。」","他顿了顿：「你如果愿意学，我可以教你。但你要想清楚——学灵魂魔法，就等于和教会作对。这条路，不好走。」",[("答应学","city_jiaohui_mercury_seals"),("再想想","city_jiaohui_intro")]),
("city_jiaohui_mystery","交汇城·密道","你按照旧书摊抄来的地图，找到城东一处废弃的磨坊。磨坊的碾盘底下，果然有一块松动的石板。","你搬开石板，露出向下的石阶。你点起火把，走下去——密道不长，尽头是一扇铁门。门上挂着一把生锈的锁，但锁芯已经被人撬过了。","你推开门。里面是一间密室，堆着十几个木箱。你打开其中一个——里面是空的，但箱底残留着一层黑色粉末。你沾了一点闻了闻，有一股刺鼻的药味。","你退出来，把石板重新盖好。这些木箱、粉末、密道——交汇城的暗流，比你想象的还要深。",[("回街市打听","city_jiaohui_suspicious"),("去找王管事","city_jiaohui_wang_guide")]),
("city_jiaohui_scroll","交汇城·旧卷轴","你在图书馆的角落，发现一卷被遗忘的旧卷轴。它被压在几本厚书下面，落满了灰。","你展开卷轴，上面用一种古老的文字写着什么。你认不全，但有几个词你见过——「七印」「黄林晶」「铸印」。","你拿着卷轴去问管理员。管理员看了一眼，摇头：「这东西放了几十年了，没人看得懂。你要是感兴趣，可以借去研究。」","你把卷轴卷好，收进怀里。你有一种直觉：这卷轴，和你在沙漠里拿到的那封信，说的也许是同一件事。",[("仔细研究卷轴","city_jiaohui_mercury_seals"),("去找墨丘利请教","city_jiaohui_mercury_queen")]),
("city_jiaohui_suspicious","交汇城·可疑之人","你在街市上注意到一个奇怪的人。他穿着普通的商贩衣服，但眼神一直飘——不是在看货，是在看人。","他跟了你两条街。你故意拐进一条小巷，在拐角处停住。他果然跟了进来，你迎面堵住他：「阁下，跟了我一路，想买点什么？」","他愣了一下，随即笑了：「眼力不错。我叫老吴，替人跑腿的。有人托我问你——是不是要去『北边』？」「北边？」你心里一紧，「谁问的？」","他没有回答，只递给你一张纸条，就转身走了。纸条上写着一行字：「北边的风大，夜里小心。」你捏着纸条，站在巷子里，若有所思。",[("查老吴的底细","city_jiaohui_wang_guide"),("把纸条收好","city_jiaohui_intro")]),
("city_jiaohui_wang_guide","交汇城·王管事","你找到商会的王管事——他是你在交汇城最熟的一个人。","「你要打听老吴？」王管事正在拨算盘，听了你的话，手顿了一下，「老吴是城里的『包打听』，专门替人传话收钱。但这两年，他接的单子越来越怪。」","「怪在哪？」你问。他压低了声音：「他替『那边』传话。」他没有说哪边，但你明白他的意思。","他拨了两下算盘，又说：「你要是被老吴盯上了，说明『那边』的人也注意到你了。你自己小心。」他顿了顿，「还有——你要是真要去北边，替我带一封信给铁门关的赵家兄弟。老朋友了，多年没见。」",[("接过信","city_jiaohui_explore"),("问那边是谁","city_jiaohui_suspicious")]),
("city_jiaohui_weapon","交汇城·武器店","你走进城西的武器店。墙上挂满了刀剑，空气里弥漫着铁和油脂的气味。","店主是个膀大腰圆的中年人，正在打磨一把长刀。他看了你一眼：「看剑？看刀？还是看护具？」「看看剑。」你说。","他放下手里的活，从架上取下一把剑递给你。你掂了掂，分量正好。你问他价格，他说了一个数——你摸了摸口袋，叹了口气。","店主笑了：「买不起？那看看这边。」他指着一排旧货，「这些都是别人典当的，价格便宜。虽然旧，但都是好铁打的。」你挑了一把合手的旧剑，付了钱。剑入手，沉甸甸的，像是一个故事。",[("付钱买剑","city_jiaohui_explore"),("再挑一件护具","city_jiaohui_intro")]),
("city_tiemenguan_army","铁门关·军营","你走进铁门关的军营。校场上，一队士兵正在操练，喊杀声震天。","领兵的军官看见你，走了过来：「你是……学院来的？」你点点头。他打量了你几眼：「学院的人，来我们这穷地方，少见。」","「想看看北边的局势。」你说。他沉默了一会儿，把你带到城墙边，指着远处：「那边，三十里外，是深渊的边界。每年冬天，那些东西就会往南试探。」","「我们挡了十年了。」他拍了拍城墙的砖，「砖换了一批又一批，人换了一批又一批。但只要这面墙还在，它们就过不来。」你站在墙边，听着风从北方吹来，像一声低沉的号角。",[("谢谢他","city_tiemenguan_intro"),("问深渊的事","city_tiemenguan_explore")]),
("city_tiemenguan_explore","铁门关·城防","你在铁门关的城墙上走了一圈。城墙很厚，但墙面上布满了修补的痕迹——新砖压着旧砖，像一道巨大的伤疤。","城下的军械库里，堆满了修补过的武器。一个老铁匠正叮叮当当地敲打着一把卷刃的刀。你问他：「这些武器，都是修过的？」","「修？」他哼了一声，「打出来就是旧的。北边的仗，耗武器比耗人多。新刀出库，三个月就卷刃——不是刀不好，是仗太勤。」","你摸着城墙上的砖，砖缝里嵌着碎铁和黑褐色的痕迹。你忽然明白，铁门关这三个字，是用什么写成的。",[("去酒馆坐坐","city_tiemenguan_zhao_brothers"),("继续看城墙","city_tiemenguan_army")]),
("city_tiemenguan_zhao_brothers","铁门关·赵家兄弟","你在铁门关的酒馆里，找到了赵家兄弟。他们是本地人，哥哥叫赵大，弟弟叫赵二，都在守军里当差。","「王管事的信？」赵大接过信，粗粝的手指小心地拆开，「那老家伙，还惦记着我们呢。」他看完信，沉默了一会儿，把信收进怀里。","「他信里说，你也要去北边？」赵大问你。你点点头。赵二在旁边插嘴：「北边可不太平。你要是去，记住——晚上别离火堆太远。」","赵大瞪了弟弟一眼，又转向你：「不过既然是他托你带的信，我们欠你个人情。你要是需要什么帮忙，说一声。」你谢过他们，在酒馆里喝了一碗热酒。酒很烈，像铁门关的冬天。",[("谢过他们","city_tiemenguan_explore"),("打听北边的路","city_tiemenguan_army")]),
("city_nanfang_chen_guide","南方港城·陈向导","你在港口的船坞边，找到了陈向导。他是个老水手，皮肤被海风和日头晒成了古铜色。","「你要出海？」他上下打量你，「看你这身板，不是海上长大的吧。」「不是。」你老实承认。「那得先说好——海上的规矩，不听船长的，就会被扔下去喂鱼。」","他领你去看船。他的船叫「浪里白」，不大，但收拾得干净。你在甲板上站了一会儿，看着远处的大海，心里忽然有点发怵。","「怕海？」陈向导笑了，「我第一次出海也怕。后来才知道，海不记仇——你怕它，它也那样；你不怕它，它还那样。」他拍了拍船舷，「走吧，先教你认缆绳。」",[("上船学习","city_nanfang_explore"),("问航线的事","city_nanfang_tavern")]),
("city_nanfang_explore","南方港城·码头","你在南方港城的码头上闲逛。船桅如林，帆布如云，空气中弥漫着海盐、鱼干和香料的气味。","你看见一艘卸货的商船，水手们正把一箱箱货物搬下船。你注意到，其中几只箱子贴着「北」字标签——北方的东西，怎么会从南方的港卸下来？","你走近想看看，被一个监工拦住了：「看什么看？让开让开！」你退到一旁，但那几口箱子，被你记在了心里。","傍晚，你坐在码头边，看着夕阳把海面染成金红色。你想起那个贴「北」字的箱子，心里隐隐觉得，有什么事，正在这座城和那座城之间流动。",[("回码头打听","city_nanfang_tavern"),("找陈向导出海","city_nanfang_chen_guide")]),
("city_nanfang_tavern","南方港城·酒馆","你走进码头边的「美人鱼」酒馆。这里的水手比酒还多，人声比浪声还响。","你要了一碗酒，在吧台边坐下。旁边一个喝得半醉的水手正跟人吹牛：「……那回我在深海里，看见一座城！白的，像珊瑚做的，还会发光！」","「吹吧你！」他的同伴哄笑。他急了：「真的！我发誓！就在那片黑水底下——老辈人都知道，那底下住着『他们』！」","你端着酒，听着他们的争吵。深海、白城、发光——你想起在沙漠里那封信上，也有类似的描述。你放下酒碗，记住了这个水手的名字。",[("找他细聊","city_nanfang_explore"),("继续喝酒","city_nanfang_chen_guide")]),
("city_holy_academy","圣城·神学院","圣城的圣光神学院，坐落在教堂区的高地上。你站在学院门前，抬头看着那座尖顶的建筑。","学院的学生们穿着白袍，三三两两地从大门进出。你注意到，他们走路时都低着头，脚步很轻，像是怕惊动什么。","你拦住一个学生，问他学院教些什么。他看了你一眼，声音压得很低：「教……教圣典、教仪轨、教净化术。还有——」他顿了顿，「教怎么辨认『不洁之人』。」","他没有多说，匆匆走了。你站在学院门口，看着那座漂亮的建筑，心里却掠过一丝凉意。",[("进去看看","city_holy_mass"),("先去教堂","city_holy_inn")]),
("city_holy_forgiven","圣城·被宽恕的人","你在圣城的广场上，遇到一个被「宽恕」的人。他跪在教堂前的石阶上，脖子上挂着一块铁牌。","铁牌上刻着字：「我曾是不洁之人，感谢圣光宽恕。」他的眼睛很空，像一潭死水。你问他：「宽恕……是什么感觉？」","他抬起头，看了你很久，声音沙哑：「像……被剥了一层皮，又被告知，这是恩赐。」他说完，又低下头，不再说话。","你站在他面前，很久没有动。你想起圣城那些关于「净化」的传说——所谓的宽恕，到底是救赎，还是另一种刑罚？",[("去教堂里看看","city_holy_mass"),("去找神父聊聊","city_holy_academy")]),
("city_holy_inn","圣城·旅店","你住进圣城的一间旅店。店名很朴素，叫「朝圣者之家」，墙上的壁画画着天使和圣徒。","夜里，你听见隔壁房间有哭声。你敲了敲门，门开了一条缝——是一个妇人，抱着一个包袱，满脸泪痕。","「怎么了？」你问。她哽咽着说：「我的孩子……被审判所带走了。他们说他是『不洁之人』……他只是会一点治愈术啊。」","你不知该如何安慰她。她哭了一会儿，擦干眼泪，把包袱抱紧：「我要去求主教。求他开恩。」你看着她走进夜色里的背影，心里沉甸甸的。",[("跟上去看看","city_holy_inquisition_talk"),("留在旅店","city_holy_forgiven")]),
("city_holy_inquisition_sneak","圣城·夜探审判所","你趁着夜色，摸到审判所的后墙。这里是圣城最森严的地方，连墙壁都透着一股冷意。","你翻进后院，贴着墙根移动。你看见一扇亮着灯的小窗，窗缝里透出说话声：「……这批『不洁之人』，明天早上行刑。」「都查过了？」「查过了，罪名无误。」","你的心一沉。你从窗缝往里看——火把的光下，几个穿黑袍的人正在翻着一本名册。名册上，密密麻麻全是名字。","你记住了一个名字：约拿。你退出来，翻墙离开。夜风很冷，你裹紧袍子，心里想着那个名字。",[("想办法救人","city_holy_inquisition_talk"),("先离开圣城","city_holy_forgiven")]),
("city_holy_inquisition_talk","圣城·审判所","你走进审判所，说要为一个人申诉。接待你的执事听完你的话，面无表情：「你说的人是灵魂法师。」","「他只是会一点治愈术。」你说。执事翻了一页卷宗：「治愈术在圣城，是神的恩典；灵魂魔法，是魔鬼的馈赠。你分不清吗？」","「我分得清。」你说，「但我不确定，你们分不分得清。」执事抬起头，看了你很久。他最终没有发作，只是合上卷宗：「你的申诉，我会呈上去。但别抱太大希望。」","你走出审判所，站在午后的阳光里。你知道，你的申诉大概不会有用——但至少，你说了。",[("等消息","city_holy_mass"),("离开圣城","city_holy_intro")]),
("city_holy_mass","圣城·弥撒","你参加了圣城大教堂的弥撒。教堂里烛火通明，唱诗班的歌声在穹顶下回荡。","主教穿着金线织成的祭袍，站在高台上宣讲。他的声音洪亮而慈祥：「圣光眷顾着每一个迷途的灵魂——只要你们愿意放下罪孽，回到光的怀抱。」","你站在人群里，听着周围信徒的祈祷声。你忽然注意到，前排有一个穿黑袍的人——他没有祈祷，只是在观察。他注意到你的目光，冲你微微点了点头。","弥撒结束后，你走出教堂。那个人已经不见了。你站在教堂前的台阶上，看着人群散去，心里升起一种说不清的感觉：这座圣城，圣光的底下，藏着太多东西。",[("去找那个黑袍人","city_holy_inquisition_sneak"),("回旅店","city_holy_inn")]),
("city_ironpeak_buy","铁峰堡·交易","铁峰堡的市集，开在一条宽阔的矿洞里。两旁的摊位摆满了铁器、矿石和宝石，炉火把洞壁映得通红。","你在一家铁器摊前停下，看中了一把短刀。摊主是个壮实的矮人，他拿起刀，在拇指上试了试刃：「好刀。你看这纹路——钢是百炼的。」","你问他价格。他说了一个数，你觉得有些贵，正要还价，他抢先说：「不还价。铁峰堡的规矩，东西值多少，就卖多少。我要是抬价，明天锤子都拿不稳。」","你付了钱，把短刀别在腰上。你想起矮人的那句老话：锤子可以借，手艺不能丢。这句话，大概也是他们做生意的底气。",[("继续逛市集","city_ironpeak_listen"),("去熔炉看看","city_ironpeak_furnace")]),
("city_ironpeak_copper_lie","铁峰堡·铜矿之谎","你在铁峰堡的矿工酒馆里，听到一个关于「铜矿」的传闻。","「新开的那条矿脉，说是铜矿。」一个矿工压低声音说，「但我去看过——那矿脉的颜色不对。铜是黄的，那东西，泛着黑。」","「你少胡说。」他同伴打断他，「矿主说了，那就是铜矿，只是成色差点。」「成色差点？」矿工哼了一声，「我在这行干了三十年，分得清铜和别的东西。」","你记住了他们的对话。黑矿、矿主、封锁的消息——铁峰堡的地下，藏着的东西，比铜贵重的多，也危险得多。",[("去那条矿脉看看","city_ironpeak_copper_truth"),("继续喝酒","city_ironpeak_drink")]),
("city_ironpeak_copper_truth","铁峰堡·矿脉真相","你沿着传闻，找到了那条新开的矿脉。矿口被重兵把守，但你绕到后山，从一处废弃的通风口爬了进去。","矿道很深，越往里走，墙壁的颜色越深。你捡起一块矿石——它泛着黑紫色的光，入手冰凉，像一块凝固的暗影。","你想起在矮人古画上见过的图案：一颗跳动的心，埋在深山里。你握紧那块矿石，心里有个声音说：这不是铜。这是别的东西。","你把矿石揣进怀里，从通风口退了出来。你回到铁峰堡，没有把这件事告诉任何人——但你决定，找机会问问那些老矿工。",[("找老矿工打听","city_ironpeak_listen"),("去问长老","city_tiefeng_elders")]),
("city_ironpeak_drink","铁峰堡·酒馆","你走进铁峰堡的「大熔炉」酒馆。这里的酒比水多，矮人们围坐在长桌边，举着大杯，声浪震天。","你挤到吧台，要了一杯麦酒。酒很烈，像喝下一口烧红的铁。你咳了两声，旁边的矮人哈哈大笑：「第一次喝？习惯了就好！」","他跟你碰了碰杯：「我叫铁砧。你是从地上来的？地上的人，总嫌我们的酒太烈。」「是有点烈。」你老实说。「那就对了！」他大笑，「不烈，还叫酒吗？」","你和他喝了几杯，聊起了铁峰堡的事。铁砧喝到兴头上，拍着桌子说：「我告诉你，我们矮人，别的不行，就是倔。认准的事，锤子砸不弯。」",[("继续喝酒","city_ironpeak_listen"),("问矿脉的事","city_ironpeak_copper_lie")]),
("city_ironpeak_furnace","铁峰堡·永恒熔炉","你站在铁峰堡的永恒熔炉前。它比传说中还要壮观——一炉永不熄灭的火焰，散发着足以融化钢铁的热浪。","熔炉旁的锻造台上，一位老矮人正专注地敲打着一块通红的铁坯。他的动作沉稳有力，每一锤都落在同样的位置。","你没有打扰他，只是站在一旁看着。过了很久，他停下锤子，抬头看你：「年轻人，看炉子，还是看火？」","「都看。」你说。他笑了：「看炉子，看的是规矩；看火，看的是心气。你两个都看——那你是来学手艺的。」他指了指旁边的一柄铁锤：「拿起来。试试。」",[("拿起铁锤","city_ironpeak_learn"),("谢谢他","city_ironpeak_intro")]),
("city_ironpeak_learn","铁峰堡·学艺","你拿起那柄铁锤，学着老矮人的样子，敲打那块铁坯。","第一锤，你砸偏了。铁坯从台子上跳起来，差点砸到你的脚。老矮人哈哈一笑：「不错，至少没扔锤子跑。」","你继续敲。一锤，两锤，三锤。你的手臂开始发酸，但铁坯在你的敲打下，渐渐变了形状。","「好了。」老矮人接过锤子，「第一次打铁，能打到这个程度，算有天分。」他把那块铁坯放进水里淬火，取出来递给你：「拿着。自己打的第一件东西，值得留一辈子。」你接过那块温热的铁，郑重地收进怀里。",[("谢过老师傅","city_ironpeak_furnace"),("去市集买工具","city_ironpeak_buy")]),
("city_ironpeak_listen","铁峰堡·听矿工说话","你蹲在矿工的休息棚边，听他们聊天。","「……前天塌了一段巷道，死了两个人。」一个年轻矿工说。「矿主怎么说的？」「说是『意外』。但我知道，那巷道是他们瞒着大家挖的——挖得太深了。」","「别说了。」老矿工打断他，「有些事，知道了也改不了。我们还得吃饭。」年轻矿工没再说话，低头拧着帽子。","你听着他们的对话，心里沉甸甸的。铁峰堡的地底，埋着矿，埋着火，也埋着这些人的沉默。",[("去矿井看看","city_ironpeak_copper_truth"),("找长老问问","city_tiefeng_elders")]),
("city_ironpeak_palace","铁峰堡·王宫","你来到铁峰堡的王宫。说是王宫，其实更像一座巨大的堡垒——石墙厚重，门楣上刻着古老的符文。","卫兵拦住你。你说明来意——你是学院的使者，想了解矮人王国的状况。卫兵进去通报，过了一会儿，带你进了议事厅。","矮人王坐在石座上，比传闻中更魁梧。他打量了你一番，声音低沉：「学院的使者？你们人类，终于想起我们这些『地底人』了？」","他没有等你回答，挥了挥手：「坐吧。既然来了，就听听——这座山底下，最近出了些怪事。」",[("坐下听他说","city_tiefeng_elders"),("问怪事是什么","city_ironpeak_copper_lie")]),
("city_lvzhou_desert","绿洲城·沙漠","你站在绿洲城的城墙上，看着外面无边无际的沙漠。风从沙丘间穿过，像一声长长的叹息。","「沙漠里，什么东西都有。」一个守城的卫兵对你说，「有商队，有强盗，有沙盗——还有比沙盗更可怕的东西。」","「什么？」你问。他压低声音：「听老辈人说，沙漠深处，有一片『黑沙』。踩上去的人，会做同一个梦——梦见自己走在一座会发光的城里。」","「然后呢？」「然后？」卫兵笑了笑，「然后，就没人回来过了。」你听着他的话，看着远处起伏的沙丘，把那句话记在了心里。",[("出城看看","city_lvzhou_explore"),("问长老","city_lvzhou_elders")]),
("city_lvzhou_elders","绿洲城·长老","你在绿洲城找到年迈的长老。他坐在一棵老树下，手里转着两枚光滑的石球。","「年轻人，从远方来？」他眯着眼看你，「这座城里的每个人，都是从沙漠里捡回来的命——包括我。」","你问他关于黑沙的传说。他转了转石球，说：「那不是传说。我年轻时，亲眼见过一个人从黑沙里走出来——他浑身是沙，眼睛却亮得像灯。」","「他说了什么？」你问。长老沉默了一会儿：「他说，黑沙底下，有一座城。那座城里的人，都欠着一个『千年前的承诺』。」他说完，又转起石球，不再说话。",[("谢过长者","city_lvzhou_explore"),("记住他的话","city_lvzhou_desert")]),
("city_lvzhou_explore","绿洲城·探索","你在绿洲城里转了一圈。城不大，但五脏俱全：集市、水井、神庙、酒馆，都挤在这一片绿洲上。","集市上，一个商贩向你兜售「沙漠之宝」——一块发着微光的石头。你问他这是什么，他神神秘秘地说：「从黑沙里捡的。据说，能保平安。」","你没有买，但你多看了那石头几眼。它的光泽，让你想起承天山那道裂缝的蓝光——一样的不对劲。","你在城里的水井边坐下，喝了一口水。水很甜，是绿洲的味道。你抬头看着头顶的蓝天，心里却想着那些黑沙底下的传说。",[("去神庙看看","city_lvzhou_elders"),("出城走走","city_lvzhou_desert")]),
("city_nanfang_chen_guide","南方港城·陈向导","你在港口找到陈向导。他正在修补渔网，看见你，咧嘴笑了：「来得正好，帮我搭把手。」","你帮他补完网，他请你喝了一碗鱼汤。汤很鲜，你喝得干干净净。他满意地点头：「能吃，就能干活。走，带你认认港口的规矩。」","他领着你走遍码头：哪家的船可靠，哪片水域有暗流，哪些货物别碰。他的经验，都是用年岁换来的。","「记住了，」他最后说，「在海上，船是你的命，浪是你的敌，风是你的朋友——但最要紧的，是记住回家的方向。」",[("谢过陈向导","city_nanfang_explore"),("问深海的事","city_nanfang_tavern")]),
("city_shengcheng_explore","圣城·探索","你在圣城的大街小巷里走着。这里的建筑庄严宏伟，连路边的石柱都刻着经文。","你路过一间小教堂，听见里面传来祈祷声。你走进去，看见几个信徒跪在长椅上，低声念着经文。角落里，一个老修士正在擦拭烛台。","你问他：「圣城的人，都信圣光吗？」他想了想，说：「都信。但信的东西，可能不一样。」他指了指烛台：「有人信光，有人信火——火和光，是两回事。」","你走出教堂，琢磨着他的话。这座城到处都写着「圣光」，但真正理解光的人，也许没几个。",[("去图书馆","city_shengcheng_library"),("找约翰","city_shengcheng_john_guide")]),
("city_shengcheng_john_guide","圣城·约翰","你找到了约翰——一个在圣城住了几十年的老居民。他开着一间小小的杂货铺，什么都知道一点。","「圣城啊，」他擦着柜台，「好是好，就是规矩多。哪天早上起来，发现多了一条新规矩，别奇怪。」","你问他圣城最近有什么动静。他压低声音：「审判所那边，最近抓了不少人。说是『不洁之人』——但我知道，有几个，只是会治病的药师。」","「你怎么知道的？」你问。他叹了口气：「其中一个，是我看着长大的孩子。」他不再说话，只是把柜台又擦了一遍。",[("谢过约翰","city_shengcheng_library"),("去审判所看看","city_holy_inquisition_talk")]),
("city_shengcheng_library","圣城·图书馆","圣城的图书馆，藏在大教堂的侧翼。书架高得够不到顶，空气里弥漫着旧纸和蜡烛的气味。","你在一排旧书前停下，抽出一本《圣典注释》。翻开，里面夹着一张发黄的纸条，上面写着一行小字：「圣光之下，亦有阴影。——读此句者，慎言。」","你把纸条夹回书里，放回原处。你又抽出几本书翻了翻——大多是圣典、教义、仪轨。但在最底层的架子上，你发现了一本没有标题的旧册子。","你翻开它，里面记录的是一种古老的仪式，名字你从未听过：「炽天使」。你合上册子，心跳加快——这个名字，你听墨丘利提过。",[("借走册子","city_holy_inquisition_sneak"),("放回原处","city_shengcheng_explore")]),
("city_tiefeng_bottom","铁峰堡·地底深处","你沿着一条废弃的矿道，向铁峰堡的地底深处走去。空气越来越热，墙壁的颜色越来越深。","你走到矿道尽头，眼前豁然开朗——一个巨大的地下空间，穹顶高悬，四壁泛着暗红色的光。空间中央，是一道深不见底的裂缝，裂缝里传出沉闷的、心跳一样的声音。","你想起矮人古画上的图案：火焰、锤子、跳动的心。你站在裂缝边，感觉脚下的地面在微微震动。","你没有再靠近。你退出来，把矿道口用碎石掩好。有些东西，不该被看见——至少现在不该。",[("回到铁峰堡","city_tiefeng_elders"),("把发现告诉长老","city_tiefeng_elders")]),
("city_tiefeng_elders","铁峰堡·长老","你找到了铁峰堡的铸匠长老——一个胡须花白的老矮人。他正对着炉火，擦着一柄锤子。","「地底深处的事，你都看见了？」他听完你的话，没有惊讶，「那条裂缝，我们守了七百年。长老会轮流守着，不让任何人靠近。」","「那里面是什么？」你问。他沉默了很久：「是大地的心跳。也是——」他顿了顿，「我们矮人族的债。祖先欠下的，子孙来还。」","他没有再解释。你也没有再问。你只是坐在炉火旁，陪他坐了很久。",[("谢过长者","city_tiefeng_explore"),("问债是什么","city_tiefeng_bottom")]),
("city_tiefeng_explore","铁峰堡·探索","你在铁峰堡里转了一圈。这里的街道都在地下，头顶是岩壁，脚下是石板，空气里混着铁锈和硫磺的气味。","你路过一座矮人的雕像——一个举着锤子的老矮人，面容坚毅。雕像底座刻着一行字：「锤子不低头，矮人不弯腰。」","你在雕像前站了一会儿。矮人这个种族，像他们的钢铁一样——不弯，不折，宁碎不屈。","你继续往前走。路过一间工坊时，里面传来叮叮当当的敲打声，像这座地底城市的心跳。",[("去熔炉","city_ironpeak_furnace"),("去酒馆","city_ironpeak_drink")]),
("city_yinye_elders","银叶城·长老","你在银叶城的世界树下，见到了精灵长老。他的白发垂到胸前，眼睛像两汪深潭。","「人类的旅行者。」他看着你，「你带着风尘和心事而来。说吧，你想从银叶城得到什么？」","「我想知道世界树的事。」你说，「还有——为什么精灵们，看起来都很疲惫。」","长老沉默了很久。他伸手抚过世界树的树干，说：「树在衰老。不是因为它老了——是因为，它心里压着一些事。一些……很久以前就该被说出的话。」他没有再往下说，但你看见，他握着树干的手，在微微发抖。",[("问树压着什么","city_yinye_roots"),("谢过长者","city_yinye_explore")]),
("city_yinye_explore","银叶城·探索","你在银叶城里走着。这座城建在世界树的枝桠之间，房屋依树而建，街道蜿蜒如藤蔓。","精灵们走在街上，步履轻缓，说话声像风穿过树叶。你注意到，他们的神情大多平和，但偶尔——你捕捉到一两道疲惫的目光。","你在一间树屋里，遇到一位老精灵正在编织银色的丝线。你问她：「精灵们的生活，一直这么平静吗？」","她停下手中的活计，想了想：「平静……是我们努力维持的东西。」她低下头，继续编织，「有些事，我们不提，不代表不记得。」",[("问她记得什么","city_yinye_roots"),("继续逛","city_yinye_elders")]),
("city_yinye_roots","银叶城·世界树根","你来到世界树的根部。这里的树根粗如巨蟒，深深扎进大地。你把手贴在树皮上，闭上眼——你听见了那阵呢喃。","这一次，呢喃比你在序章时听得更清楚：「……松动……松动……第七根锁链……」你睁开眼，心里一紧。第七根锁链——那不是七印吗？","你绕着树根走了一圈，发现其中一条根须上，缠着一圈已经发黑的藤蔓，像是被什么腐蚀过。你伸手想碰，被一道无形的力弹开，指尖一阵发麻。","你退后几步，看着那条发黑的根须。世界树在衰老、在松动——而精灵们，还在努力维持着表面的平静。",[("把这个发现告诉长老","city_yinye_elders"),("藏在心里","city_yinye_explore")]),
("city_chengtian_explore","承天城·探索","你在承天城里走着。这座城以「天」为名，处处透着古都的气派——朱墙、飞檐、石板路，都像从旧画里搬出来的。","城里的老人说，承天城有一千年的历史，城砖缝里都嵌着故事。你在城墙根下，看见一个老人在给孩子们讲故事：「……那裂缝啊，是天上漏下来的光。谁要是靠近它，就能看见过去。」","「看见过去？」你停下脚步。老人看了你一眼：「是啊。有人看见自己小时候，有人看见自己没出生的时候。但没人敢靠近它——因为看多了过去，就走不回现在了。」","你站在人群外，听着那个故事。你想起承天山，想起那道时光裂隙。这座古都，和那个传说，像隔着一层薄纱。",[("找李向导打听","city_chengtian_li_guide"),("去承天山看看","city_chengtian_mountain")]),
("city_chengtian_li_guide","承天城·李向导","你在承天城找到了李向导——一个在城里住了大半辈子的老学究。他戴着一副旧眼镜，说话慢条斯理。","「你要问承天城的事？」他推了推眼镜，「这座城，讲究一个『厚』字——城厚、史厚、人情厚。但也厚得让人喘不过气。」","「为什么？」你问。他想了想：「因为这座城，记得太多事了。一千年的事，全压在肩上，能不沉吗？」","他顿了顿，又说：「城北那座山，叫承天山。山上有一道裂缝，城里的老人说那是『天眼』——但没人敢去验。你要是想去，我劝你，别一个人去。」",[("谢过李向导","city_chengtian_mountain"),("去城北看看","city_chengtian_explore")]),
("city_chengtian_mountain","承天城·承天山","你去了承天山。山不算高，但山势沉厚，像一头伏卧的巨兽。你沿着山路往上走，越走，风越凉。","在半山腰，你发现一处被灌木遮住的岩壁。你拨开灌木，看见岩壁上刻着一些字——被风雨侵蚀得模糊了，但你依稀认出几个：「……七……印……勿……近……」","你的心跳漏了一拍。你蹲下来，仔细辨认那些字。刻痕很深，像是用利器一笔一笔凿出来的。刻这些字的人，一定很用力。","你站起来，看了看山顶。山顶的云雾在缓缓流动。你犹豫了一下，没有继续往上——有些东西，你知道它在那里，就够了。",[("下山","city_chengtian_explore"),("继续上山","city_chengtian_intro")]),
]

def build(nid, place, text, opts):
    return '''N["%s"]=function(){return{
place:"%s",
text:[
%s
],
options:[
%s
]
}};''' % (nid, place,
   ",\n".join('"%s"' % t.replace('"','「') for t in text),
   ",\n".join('{t:"%s", go:"%s"}' % (o[0].replace('"','「'), o[1]) for o in opts))

import re
html = open('game.html','r',encoding='utf-8').read()
replaced = 0
for item in R:
    nid, place, opts = item[0], item[1], item[-1]
    text = list(item[2:-1])
    pat = re.compile(r'N\["%s"\]=function\(\)\{return\{.*?\n\}\};' % nid, re.S)
    if pat.search(html):
        html = pat.sub(lambda m: build(nid, place, text, opts), html, count=1)
        replaced += 1
    else:
        print('✗ 未找到: %s' % nid)
header = "\n\n// v41 占位重写·第三批（%d个 城市探索）\n" % len(R)
pos = html.rfind('</script>')
if pos > 0:
    html = html[:pos] + header + "\n" + html[pos:]
open('game.html','w',encoding='utf-8').write(html)
print('✓ 已替换 %d / %d' % (replaced, len(R)))
